_BASE_AGENT = _BASE_NS["agent"]
_OPERATOR = _OP_NS['sale_advance']
_OPERATOR_CONFIGURATION = {'sale_advance_lookahead': 7, 'sale_advance_abstain_on_weed': True}

def _find_tape_hooks(namespace):
    seen = set()
    while isinstance(namespace, dict) and id(namespace) not in seen:
        seen.add(id(namespace))
        selector = namespace.get("_selected_tape")
        impl = namespace.get("_IMPL")
        if callable(selector) or impl is not None:
            return selector, impl
        namespace = namespace.get("_BASE_NS")
    return None, None

_PARENT_TAPE_SELECTOR, _PARENT_IMPL = _find_tape_hooks(_BASE_NS)

def _selected_tape(observation):
    if callable(_PARENT_TAPE_SELECTOR):
        return _PARENT_TAPE_SELECTOR(observation)
    if _PARENT_IMPL is None:
        return None
    try:
        player = int(observation.get("player", 0))
        step = int(observation.get("step", 0))
        native = _PARENT_IMPL.chassis.players[player]
        route = 2 if step >= 648 else native.get("route", 0)
        return SimpleNamespace(
            route_id=f"local-best-native-{route}",
            actions=tuple(_PARENT_IMPL.chassis.routes[route]),
        )
    except Exception:
        return None

def agent(observation, configuration=None):
    action = _BASE_AGENT(observation, configuration)
    tape = (_selected_tape(observation)
            if 'sale_advance' in {"market_queue_lockstep", "racegate_reservation",
                                  "opponent_front_run", "adaptive_market_tape_guard",
                                  "sale_advance"}
            else None)
    return _OPERATOR(observation, action, _OPERATOR_CONFIGURATION, tape)
